//! Cargo-driven `wlnotify.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is wlnotify-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x6c910000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7fe44000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7fe44000000u64)),
        o => panic!("wlnotify-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine"],
        "x86_64" => &["engine:wine"],
        "aarch64" => &["engine:wine"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("wlnotify-rust")
        .resource_from_rc("dll/win32/wlnotify/wlnotify.rc", "wlnotify_res")
        .spec2def("dll/win32/wlnotify/wlnotify.spec", "wlnotify.dll")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
